/// The magic prefix with memory id `id`: (English name, `levelreq`); `None` if unknown.
#[must_use]
pub fn prefix(id: u16) -> Option<(&'static str, u32)> {
    PREFIXES
        .binary_search_by_key(&id, |&(i, _, _)| i)
        .ok()
        .and_then(|i| PREFIXES.get(i))
        .map(|&(_, name, lvl)| (name, lvl))
}

/// The magic suffix with memory id `id`: (English name, `levelreq`); `None` if unknown.
#[must_use]
pub fn suffix(id: u16) -> Option<(&'static str, u32)> {
    SUFFIXES
        .binary_search_by_key(&id, |&(i, _, _)| i)
        .ok()
        .and_then(|i| SUFFIXES.get(i))
        .map(|&(_, name, lvl)| (name, lvl))
}

/// The misc.txt row with item code `code`: (`levelreq`, English name); `None` if unknown.
#[must_use]
pub fn misc(code: &str) -> Option<(u32, &'static str)> {
    MISC.binary_search_by_key(&code, |&(c, _, _)| c)
        .ok()
        .and_then(|i| MISC.get(i))
        .map(|&(_, lvl, name)| (lvl, name))
}

/// The English name of the vendor NPC with monstats row `txt`; `None` for other monsters.
#[must_use]
pub fn vendor(txt: u32) -> Option<&'static str> {
    VENDORS
        .binary_search_by_key(&txt, |&(i, _)| i)
        .ok()
        .and_then(|i| VENDORS.get(i))
        .map(|&(_, name)| name)
}
